tests_py:
def test_known_backup():
    assert solution.backup_all([2.0], [(1.0, 0)], 0.9) == [2.8]

def test_two_states():
    new = solution.backup_all([0.0, 5.0], [(0.0, 1), (1.0, -1)], 0.5)
    assert new == [2.5, 1.0]

def test_terminal_gets_no_future():
    assert solution.backup_all([100.0], [(1.0, -1)], 0.9) == [1.0]

def test_gamma_zero():
    assert solution.backup_all([3.0], [(2.0, 0)], 0.0) == [2.0]

def test_does_not_mutate():
    values = [1.0, 2.0]
    solution.backup_all(values, [(0.0, 1), (0.0, 0)], 0.9)
    assert values == [1.0, 2.0]

def test_length_mismatch():
    try:
        solution.backup_all([1.0], [(0.0, 0), (0.0, 0)], 0.9)
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_invalid_gamma():
    try:
        solution.backup_all([1.0], [(0.0, 0)], 1.5)
    except ValueError:
        return
    raise AssertionError("expected ValueError")
